const crypto = require('crypto');

const SIGNING_SECRET = $env.TALLY_SIGNING_SECRET || '';

const LABEL_MAP = {
  'full name': 'full_name',
  'work email': 'email',
  'what are you trying to solve?': 'message',
  'company size': 'company_size',
  'timeline': 'timeline',
};

function verifySignature(rawBody, signature) {
  if (!SIGNING_SECRET || SIGNING_SECRET.startsWith('placeholder')) {
    throw new Error('TALLY_SIGNING_SECRET is not configured');
  }
  if (!signature) return false;
  const expected = crypto
    .createHmac('sha256', SIGNING_SECRET)
    .update(rawBody)
    .digest('base64');
  try {
    return crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signature));
  } catch {
    return false;
  }
}

function fromTally(body) {
  const d = body.data || {};
  const out = {};
  for (const f of (d.fields || [])) {
    const key = LABEL_MAP[String(f.label || '').trim().toLowerCase()];
    if (!key) continue;
    let v = f.value;
    if (Array.isArray(v)) {
      v = v.map(id => (f.options || []).find(o => o.id === id)?.text ?? id).join(', ');
    }
    out[key] = typeof v === 'string' ? v.trim() : v;
  }
  return {
    submission_id: d.submissionId || d.responseId || body.eventId,
    submitted_at: d.createdAt || body.createdAt || new Date().toISOString(),
    ...out,
  };
}

function fromPlain(body) {
  return {
    submission_id: body.submission_id || `manual-${Date.now()}`,
    submitted_at: body.submitted_at || new Date().toISOString(),
    full_name: body.full_name,
    email: body.email,
    message: body.message,
    company_size: body.company_size,
    timeline: body.timeline,
  };
}

const results = [];

for (const item of $input.all()) {
  const headers = item.json.headers ?? {};
  const rawBody = item.json.rawBody ?? item.json.body ?? '';

  let body;
  if (typeof rawBody === 'string' && rawBody.length) {
    try { body = JSON.parse(rawBody); } catch { throw new Error('Body is not valid JSON'); }
  } else {
    body = item.json.body ?? item.json;
  }

  const sig = headers['tally-signature'];
  if (sig) {
    const raw = typeof rawBody === 'string' ? rawBody : JSON.stringify(body);
    if (!verifySignature(raw, sig)) throw new Error('Invalid webhook signature');
  }

  const parsed = body?.data?.fields ? fromTally(body) : fromPlain(body);

  if (!parsed.email) throw new Error('Missing email in submission');

  parsed.email = String(parsed.email).trim().toLowerCase();
  parsed.domain = parsed.email.split('@')[1] || null;
  parsed.started_at_ms = Date.now();
  parsed.signature_verified = Boolean(sig);

  results.push({ json: parsed });
}

return results;

const FREE = new Set([
  'gmail.com','yahoo.com','yahoo.co.uk','outlook.com','hotmail.com','hotmail.co.uk',
  'live.com','msn.com','icloud.com','me.com','mac.com','aol.com',
  'proton.me','protonmail.com','pm.me','gmx.com','gmx.net','zoho.com',
  'yandex.ru','yandex.ua','mail.ru','ukr.net','i.ua','meta.ua','bigmir.net'
]);

const DISPOSABLE = new Set([
  'mailinator.com','10minutemail.com','guerrillamail.com','tempmail.com',
  'throwawaymail.com','yopmail.com','trashmail.com','sharklasers.com',
  'getnada.com','maildrop.cc','temp-mail.org','dispostable.com',
  'fakeinbox.com','mailnesia.com','tempr.email','moakt.com'
]);

const ROLE = new Set([
  'info','support','admin','sales','contact','hello','office','help','team',
  'noreply','no-reply','donotreply','billing','accounts','marketing',
  'webmaster','postmaster','abuse','careers','jobs','hr'
]);

const RE = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i;

return $input.all().map(item => {
  const j = { ...item.json };
  const email = String(j.email || '');
  const [local, domain] = email.split('@');

  let cls = 'business';
  if (!RE.test(email))                          cls = 'invalid';
  else if (DISPOSABLE.has(domain))              cls = 'disposable';
  else if (FREE.has(domain))                    cls = 'free';
  else if (ROLE.has(String(local).toLowerCase())) cls = 'role';

  j.email_class   = cls;
  j.should_enrich = (cls === 'business' || cls === 'role');
  j.needs_mx      = (cls !== 'invalid' && cls !== 'disposable');

  return { json: j };
});

const src = $('Classify Email').all();

return $input.all().map((item, i) => {
  const base = { ...(src[i]?.json ?? src[0]?.json ?? {}) };

  let dns = item.json;
  if (typeof dns?.data === 'string') {
    try { dns = JSON.parse(dns.data); } catch { dns = {}; }
  } else if (dns?.data && typeof dns.data === 'object') {
    dns = dns.data;
  }

  const answers = Array.isArray(dns.Answer) ? dns.Answer : [];
  base.mx_valid = answers.some(a => a.type === 15);
  base.mx_status = dns.Status ?? null;

  return { json: base };
});

const src = $('Classify Email').all();

return $input.all().map((item, i) => ({
  json: {
    ...(src[i]?.json ?? src[0]?.json ?? {}),
    mx_valid: true,
    mx_check_failed: true,
  }
}));

const MAX_CHARS = 5000;
const src = $('Should Enrich?').all();

function htmlToText(html) {
  if (!html || typeof html !== 'string') return '';
  return html
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<svg\b[^>]*>[\s\S]*?<\/svg>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<\/(p|div|h[1-6]|li|section|tr|br)\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&[a-z]+;/gi, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function pick(html, re) {
  const m = String(html || '').match(re);
  return m ? m[1].trim() : '';
}

return $input.all().map((item, i) => {
  const base = { ...(src[i]?.json ?? src[0]?.json ?? {}) };

  const html = typeof item.json.data === 'string'
    ? item.json.data
    : (typeof item.json.body === 'string' ? item.json.body : '');

  const text = htmlToText(html);
  const title = pick(html, /<title[^>]*>([^<]*)<\/title>/i);
  const meta  = pick(html, /<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["']/i);

  const combined = [
    title && `TITLE: ${title}`,
    meta  && `META: ${meta}`,
    text
  ].filter(Boolean).join('\n\n').slice(0, MAX_CHARS);

  let status = 'ok';
  if (!html)                  status = 'failed';
  else if (text.length < 200) status = 'thin';

  base.website_content   = combined;
  base.website_title     = title;
  base.enrichment_status = status;
  base.website_chars     = combined.length;

  return { json: base };
});

const src = $('Should Enrich?').all();
const seen = new Set();
const out = [];

$input.all().forEach((item, i) => {
  const base = { ...(src[i]?.json ?? src[0]?.json ?? {}) };
  if (seen.has(base.submission_id)) return;
  seen.add(base.submission_id);

  out.push({ json: {
    ...base,
    website_content: '',
    website_title: '',
    enrichment_status: 'failed',
    website_chars: 0,
    fetch_error: String(item.json.error?.message ?? item.json.message ?? 'fetch failed').slice(0, 200),
  }});
});

return out;

return $input.all().map(item => ({
  json: {
    ...item.json,
    website_content: '',
    website_title: '',
    enrichment_status: 'skipped',
    website_chars: 0,
  }
}));

