const REQUIRED = ['icp_score', 'score_reasons', 'confidence', 'personalized_opener'];
const src = $('ICP Config').all();

function extractJson(raw) {
  if (raw && typeof raw === 'object') return raw;
  let s = String(raw ?? '').trim();
  s = s.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start === -1 || end === -1) return null;
  try { return JSON.parse(s.slice(start, end + 1)); } catch { return null; }
}

return $input.all().map((item, i) => {
  const base = { ...(src[i]?.json ?? src[0]?.json ?? {}) };
  const j = item.json;

    function findContent(x) {
    if (x == null) return null;
    if (Array.isArray(x)) {
      for (const el of x) { const r = findContent(el); if (r) return r; }
      return null;
    }
    if (typeof x === 'object') {
      if (Array.isArray(x.output)) { const r = findContent(x.output); if (r) return r; }
      if (Array.isArray(x.content)) {
        for (const c of x.content) {
          if (c?.text !== undefined) return c.text;
          if (typeof c === 'string') return c;
        }
      }
      if (x.message?.content !== undefined) return x.message.content;
      if (x.choices?.[0]?.message?.content !== undefined) return x.choices[0].message.content;
      if (typeof x.text === 'string' || typeof x.text === 'object') return x.text;
      if (typeof x.output_text === 'string') return x.output_text;
      if (typeof x.content === 'string') return x.content;
      if (x.icp_score !== undefined) return x;
      return null;
    }
    if (typeof x === 'string') return x;
    return null;
  }

  const raw = findContent(j) ?? j;

  const usage = j.usage ?? j.tokenUsage ?? j[0]?.usage ?? {};
  base.input_tokens  = usage.prompt_tokens ?? usage.promptTokens ?? null;
  base.output_tokens = usage.completion_tokens ?? usage.completionTokens ?? null;
  base.processing_ms = Date.now() - (base.started_at_ms || Date.now());

  const parsed = extractJson(raw);
  const ok = parsed
    && REQUIRED.every(k => parsed[k] !== undefined && parsed[k] !== null)
    && Number.isFinite(Number(parsed.icp_score));

  if (!ok) {
    return { json: {
      ...base,
      llm_ok: false,
      route: 'MANUAL',
      llm_error: 'unparseable or incomplete JSON',
      llm_raw: String(typeof raw === 'string' ? raw : JSON.stringify(raw)).slice(0, 1000),
    }};
  }

  const score = Math.max(0, Math.min(10, Math.round(Number(parsed.icp_score))));
  const flags = Array.isArray(parsed.red_flags) ? parsed.red_flags : [];

  // Role-based inbox (info@, sales@, support@) has no identifiable person behind it.
  // Cap it below the HOT threshold so it never gets an auto-drafted personal reply.
  const ROLE_CAP = 7;
  const capped = base.email_class === 'role' ? Math.min(score, ROLE_CAP) : score;

  let route;
  if (flags.length > 0) {
    route = 'MANUAL';
  } else if (capped <= 2) {
    route = 'COLD';
  } else if (parsed.confidence === 'low') {
    route = 'MANUAL';
  } else if (capped >= 8) {
    route = 'HOT';
  } else if (capped >= 5) {
    route = 'WARM';
  } else {
    route = 'COLD';
  }

  delete base.website_content;
  delete base.icp_description;

  return { json: {
    ...base,
    llm_ok: true,
    icp_score: score,
    routing_score: capped,
    score_capped: capped !== score,
    score_reasons: parsed.score_reasons ?? [],
    industry: parsed.industry ?? null,
    company_size_guess: parsed.company_size_guess ?? null,
    likely_pain: parsed.likely_pain ?? null,
    personalization_source: parsed.personalization_source ?? 'none',
    personalized_opener: parsed.personalized_opener ?? '',
    suggested_next_step: parsed.suggested_next_step ?? '',
    red_flags: flags,
    confidence: parsed.confidence ?? 'medium',
    route,
  }};
});

const src = $('ICP Config').all();
const seen = new Set();
const out = [];

$input.all().forEach((item, i) => {
  const base = { ...(src[i]?.json ?? src[0]?.json ?? {}) };
  if (seen.has(base.submission_id)) return;
  seen.add(base.submission_id);

  out.push({ json: {
    ...base,
    llm_ok: false,
    route: 'MANUAL',
    llm_error: String(item.json.error?.message ?? item.json.message ?? 'LLM call failed').slice(0, 300),
    processing_ms: Date.now() - (base.started_at_ms || Date.now()),
  }});
});

  delete base.website_content;
  delete base.icp_description;

return out;

function toJsonb(v) {
  if (v === undefined || v === null) return [];
  return Array.isArray(v) ? v : [v];
}

function toInt(v) {
  const n = Number(v);
  return Number.isFinite(n) ? Math.round(n) : null;
}

const seen = new Set();
const out = [];

for (const item of $input.all()) {
  const j = item.json;

  if (!j.submission_id || seen.has(j.submission_id)) continue;
  seen.add(j.submission_id);

  let action;
  switch (j.route) {
    case 'HOT':      action = 'awaiting_approval'; break;
    case 'WARM':     action = 'nurture_queued';    break;
    case 'COLD':     action = 'declined';          break;
    case 'MANUAL':   action = 'human_review';      break;
    case 'REJECTED': action = 'filtered';          break;
    default:         action = 'unknown';
  }

  out.push({ json: {
    submission_id:       j.submission_id,
    company_size:        j.company_size ?? null,
    full_name:           j.full_name ?? null,
    email:               j.email ?? null,
    domain:              j.domain ?? null,
    message:             j.message ? String(j.message).slice(0, 4000) : null,
    email_class:         j.email_class ?? null,
    mx_valid:            typeof j.mx_valid === 'boolean' ? j.mx_valid : null,
    enrichment_status:   j.enrichment_status ?? 'not_reached',
    icp_score:           toInt(j.icp_score),
    score_reasons:       toJsonb(j.score_reasons),
    industry:            j.industry ?? null,
    likely_pain:         j.likely_pain ?? null,
    personalized_opener: j.personalized_opener ?? null,
    confidence:          j.confidence ?? null,
    red_flags:           toJsonb(j.red_flags ?? []),
    route:               j.route ?? 'UNKNOWN',
    action_taken:        action,
    processing_ms:       toInt(j.processing_ms),
    input_tokens:        toInt(j.input_tokens),
    output_tokens:       toInt(j.output_tokens),
  }});
}

return out;

