const crypto = require('crypto');

const SECRET = $env.APPROVAL_SECRET;
const BASE   = $env.N8N_PUBLIC_URL;

if (!SECRET || !BASE) {
  throw new Error('APPROVAL_SECRET or N8N_PUBLIC_URL is not configured');
}

const TTL_MS = 24 * 60 * 60 * 1000;

return $input.all().map(item => {
  const j = { ...item.json };
  const exp = Date.now() + TTL_MS;

  const payload = `${j.submission_id}.${exp}`;
  const sig = crypto.createHmac('sha256', SECRET).update(payload).digest('hex');

  const q = (action) =>
  `${BASE}/webhook/lead-confirm?sid=${encodeURIComponent(j.submission_id)}&exp=${exp}&sig=${sig}&action=${action}`;

  j.approve_url = q('send');
  j.reject_url  = q('hold');
  j.approval_expires = new Date(exp).toISOString();

  return { json: j };
});
